public class ErrorPractice {
  public static void main(String[] args) {
    int a = 10;
    int b = 0;
    int result = a / b; // Runtime error

    System.out.println("The result is: " result); // Syntax error

    int sum = a + b;
    System.out.println("The sum is: " + sum / 2); // Logic error (should be average)
  }
}

problem.solution:
public class ErrorPractice {
  public static void main(String[] args) {
    int a = 10;
    int b = 2; // Fixed runtime error (no division by zero)
    int result = a / b;

    System.out.println("The result is: " + result); // Fixed syntax error (added missing +)

    int sum = a + b;
    double average = (double) sum / 2; // Fixed logic error (correct average)
    System.out.println("The average is: " + average);
  }
}
